<script setup lang="ts">
useHead({
  bodyAttrs: {
    class: 'is-preload'
  }
})
const closeMenu = () => {
  document.body.classList.remove('is-menu-visible')
}
//const link = { name: 'contact us', path: '/contacts', hash: '#contacts' };

const i18n = useI18n()
const localeCookie = useCookie('locale')

const switchLanguage = (locale: string) => {2
  i18n.locale.value = locale
  localeCookie.value = locale
}

// при завантаженні
onMounted(() => {
  if (localeCookie.value) {
    i18n.locale.value = localeCookie.value
  }
})
import { ref } from 'vue'

const currentYear = ref(new Date().getFullYear())

function scrollToSection(id) {
  const element = document.getElementById(id)
  if (element) {
    element.scrollIntoView({ behavior: 'smooth' })
    closeMenu()
  }
}

const name = ref('')
const email = ref('')
const message = ref('')
const status = ref('')
const phone = ref('')


const sendMessage = async () => {
  try {
    await $fetch('/api/contact', {
      method: 'POST',
      body: { name: name.value, email: email.value, phone: phone.value, message: message.value }
    })
    status.value = '✅ Ваше повідомлення надіслано чекайте відповіді'
  } catch (e) {
    status.value = '❌ Спробуйте повторно відправити'
  }
}

